"""Build the consumer report from scored immutable predictions, offline."""
from dental_release.paths import expand as _release_expand
import json, pathlib, hashlib, datetime, csv, sys, resource
import numpy as np
ROOT = pathlib.Path(__file__).resolve().parents[1]
read = lambda n: json.loads((ROOT / n).read_text())
sha = lambda p: hashlib.sha256(p.read_bytes()).hexdigest()

def dump(n, o):
    (ROOT / n).write_text(json.dumps(o, indent=2, ensure_ascii=False, allow_nan=False) + '\n')

def main():
    (r1, r2, r3, r4) = [read(f'results_R{i}.json') for i in [1, 2, 3, 4]]
    scores = read('SCORES_SUPPLEMENT.json')
    ex = read('raw/extraction_summary.json')
    cbct = read('CBCT_AVAILABILITY.json')
    screen = read('SCREENING_AUDIT.json')
    verify = read('VERIFICATION.json')
    rows = read('raw/arms.json')
    sources = read('raw/source_manifest.json')
    manifest = {'retrospective': True, 'physical_measurements_run': 0, 'freeze_scope': 'Before scoring; source outcomes had already been seen. Not a blind experiment.', 'rounds': {r: {'file': f'FROZEN_PREDICTIONS_{r}.json', **read(f'FROZEN_PREDICTIONS_{r}.sha256.json')} for r in ['R1', 'R2', 'R3', 'R4']}}
    dump('FROZEN_PREDICTIONS.json', manifest)
    with (ROOT / 'EXTRACTED_ARMS.csv').open('w', newline='') as f:
        keys = ['id', 'study', 'family', 'design', 'D_mm', 'L_mm', 'Df_mm', 'rho_gcc', 'density_kind', 'cortex_mm', 'cortex_rho_gcc', 'torque_Ncm', 'sd_Ncm', 'pitch_mm', 'depth_mm', 'primary', 'observation_level', 'locator']
        w = csv.DictWriter(f, fieldnames=keys, extrasaction='ignore')
        w.writeheader()
        w.writerows(rows)
    gain = 1 - r2['gain_ratio']
    directions = [x for x in scores['contrast_summary'] if x['split'] == 'study' and x['kind'] == 'both']
    result = {'lane': 'X68-insertion-torque', 'claim_type': 'information_link', 'review_state': 'PENDING_INDEPENDENT_REVIEW', 'what_became_possible': 'Source-bound local calibration and finite available-bore selection hits the research target band in two published regimes; conditional root interval and uncertainty remain explicit. Cross-study and patient selection not established.', 'decision': 'LOCAL_CALIBRATION_RETROSPECTIVE_GAIN; CROSS_STUDY_SCALAR_TRANSFER_FAIL; PATIENT_BORE_CHOICE_UNKNOWN; RADIAL_PRESSURE_UNIDENTIFIED', 'external_referent': {'kind': 'independent_measurement', 'locator': 'doi:10.5051/jpis.2013.43.1.30 Tables2/5, https://jpis.org/pdf/10.5051/jpis.2013.43.1.30 pp.33-34; complete PU reference DOIs in raw/source_manifest.json', 'compared_quantity': 'Published peak insertion torque arm means Ncm; ISQ at identical total mean torque', 'refutes_us': True}, 'external_refutation_scope': 'Refutes sufficiency of area-density summary and successful transfer of R1 both-model. R2 interpolation errors do not refute its limited retrospective gain.', 'rounds': {r['round']: {k: r[k] for k in ['claim_type', 'verdict', 'external_referent', 'frozen_predictions_sha256', 'prereg_sha256']} for r in [r1, r2, r3, r4]}, 'metrics': {'resolution': 'POPULATION', 'model_resolution': 'PHENOMENOLOGICAL', 'R1': r1['scores'], 'R1_both_to_practice_ratios': r1['both_to_practice_ratios'], 'R2': r2['metrics'], 'R2_error_reduction_fraction': gain, 'R3_heldout_abs_ln': [v['abs_ln'] for v in r3['predictions']], 'R4': {k: r4[k] for k in ['selected_hits', 'evaluable_groups', 'prior_practice_hits', 'ordinary_control_hits', 'independent_study_families', 'general_transfer_verdict']}}, 'coverage': ex, 'arm_dropout_fraction': ex['rejected_arms'] / ex['candidate_arms'], 'screening': {'keyword_candidates': 200, 'counts': screen['candidate_source_status_counts'], 'scope': screen['claim']}, 'direction_check': directions, 'uncertainty': scores['empirical_uncertainty'], 'rigorous_physical_prediction_enclosure': 'MISSING', 'certified_mathematical_enclosures': scores['certified_fitted_polynomial_derivative_bounds'], 'target_bore': {'target_Ncm': 25, 'band_Ncm': [20, 30], 'resolution': 'PHENOMENOLOGICAL', 'R1_both_model_hits': 0, 'R1_evaluable_groups': 2, 'R1_independent_families': 1, 'R1_generalization_verdict': r1['inverse_verdict'], 'R2_continuous_candidates_mm': [v['area_based_Df_target25_mm'] for v in r2['calibrations']], 'R3_conditional_outer_sets_mm': [v['inverse']['Df_outer_interval_mm'] for v in r3['predictions']], 'R4_available_choices_mm': [v['selected']['Df_mm'] for v in r4['predictions']], 'R4_source_observed_means_Ncm': [v['selected']['observed_Ncm'] for v in r4['predictions']], 'guaranteed_single_Df_mm': None, 'patient_selection': 'UNKNOWN'}, 'sufficiency_tests': [{'round': 'R1', **r1['summary_sufficiency']}, {'round': 'R2', **r2['summary_sufficiency'], 'referent_classification_correction': 'The endpoint-preserving witness is our_own_fixture mathematically; NIST supports the interpolation remainder theorem, not physical measurements.'}, {'round': 'R3', **r3['summary_sufficiency'], 'smallest_extension_for_this_pair': 'One bit: cortical layer present/absent; alternatively one scalar Df separates this pair. Not globally sufficient for stability or pressure.'}, {'round': 'R4', **r4['summary_sufficiency']}], 'radial_pressure_MPa': None, 'cbct_availability': cbct, 'edges': [{'from': 'Published arm mean peak torque', 'to': 'K26 peak torque scoring', 'resolution': 'POPULATION', 'time_scale': 'SIMULTANEOUS', 'units': 'Ncm', 'status': 'EXTERNALLY_MEASURED', 'note': 'Same measured quantity/time as the predicted peak torque'}, {'from': 'Insertion event/peak-torque arm condition', 'to': 'Post-seating observed ISQ sufficiency test', 'resolution': 'POPULATION', 'time_scale': 'HANDOVER', 'units': 'Ncm to dimensionless ISQ', 'status': 'EXTERNALLY_OBSERVED_JOINT_CONDITION', 'note': 'Sequential observed outcomes; no claim that peak torque alone predicts stability or osseointegration'}, {'from': 'Actual final bore/contact profile', 'to': 'K26 insertion', 'resolution': 'PER_SURFACE_REGION', 'time_scale': 'HANDOVER', 'units': 'mm', 'status': 'PROPOSED_MISSING_MEASUREMENT'}, {'from': 'Individual torque-depth measurement', 'to': 'K26 insertion mechanics', 'resolution': 'PER_TOOTH', 'time_scale': 'SIMULTANEOUS', 'units': 'Ncm', 'status': 'PROPOSED_MISSING_MEASUREMENT'}, {'from': 'Insertion residual pressure', 'to': 'Primary stability', 'resolution': 'PER_SURFACE_REGION', 'time_scale': 'HANDOVER', 'units': 'MPa', 'status': 'UNKNOWN'}], 'phenomenological_debt': read('LAB_VALIDATION_SPEC.json')['first_decisive_new_information'], 'controls': {'R1': 'Actual same-information weighted least squares; independent direct weighted design solve agrees within numerical tolerance', 'R2': 'Same two-endpoint ordinary Df interpolation also fits within20%; primary comparison is practice without local torque measurements', 'R3': 'Closed-form Lagrange interpolation; numerical parity is no claim of method advantage', 'R4': 'Same-endpoint ordinary interpolation chooses1/2 target hits on same finite menu; two exposed regimes do not establish general method advantage'}, 'verification': verify, 'limitations': ['PU nominal density is not measured natural-bone mineral density. Nominal implant length and final drill diameter do not fully describe regional engagement/profile.', 'All source outcomes were seen before retrospective interpolation; frozen receipts precede scoring, not novel outcome acquisition.', 'Arm means and SD cannot establish patient bounds. Inverse intervals are conditional on exact mean response and monotonicity.', 'Only one study varies final drill at fixed measured inputs. No three-family inverse validation and no human fully paired continuous torque/cortex/drill table in extracted evidence.', 'Bayarchimeg cortex grade50/epoxy material ambiguity retained. Table n5 conflicts with methods20; no hard interval inferred from n.', 'Formal R2/R3 decomposition JSON consolidated after scoring; equations/closure restrictions were pre-run in preregs. This artifact timing is disclosed, not backdated.', 'CBCT schema/header audit only; no actual inner-cortex thickness measurement or HU calibration performed.', 'Targeted retrieval leaves187 keyword articles deferred. This is not a systematic absence proof.'], 'cost': {'source_preparation_seconds': 'UNKNOWN; screening/transcription/verification and failed retrievals included, no speed gain claimed', 'fit_validation_queries': [r1['cost'], r2['cost'], {'R3_seconds': r3['cost_seconds']}, {'R4_seconds': r4['cost_seconds']}], 'discovery': 'Four preserved construction rounds, one cross-study failure, three limited retrospective/conditional results', 'physical_acquisition': read('LAB_VALIDATION_SPEC.json')['cost'], 'fallback': 'Abstain from guaranteed/patient bore and radial pressure; emit conditional sets and missing input ports', 'threads_max': 4, 'large_arrays_written': 0, 'GPU_used': False, 'intermediate_bytes_limit': 3000000000, 'python_version': sys.version.split()[0], 'numerical_numpy_version': np.__version__}, 'artifacts': {n: sha(ROOT / n) for n in ['EXTRACTED_ARMS.csv', 'FIGURE_X68.png', 'FIGURE_X68.svg', 'FROZEN_PREDICTIONS.json', 'VERIFICATION.json', 'LAB_VALIDATION_SPEC.json', 'LAB_QUERY_DEMO.json', 'raw/ISQ_SOURCE_CHECK.json']}, 'source_manifest': sources}
    result['reproducible_code_sha256'] = {p.name: sha(p) for p in sorted((ROOT / 'code').glob('*.py'))}
    result['reproducible_code_sha256']['run_all.sh'] = sha(ROOT / 'run_all.sh')
    result['cost']['R1_fitted_models_count'] = len(read('FROZEN_PREDICTIONS_R1.json')['models'])
    result['cost']['own_directory_bytes'] = sum((p.stat().st_size for p in ROOT.rglob('*') if p.is_file()))
    dump('results.json', result)
    table = '| Information/operation | External comparison | Result | Decision |\n|---|---|---|---|\n'
    for (k, label) in [('practice', 'Area + density'), ('cortex', '+ cortex'), ('drilling', '+ drilling'), ('both', '+ both')]:
        table += f"| R1 {label} | 38 PU arm means, study-out / family-out | {r1['scores']['study']['candidate_ridge'][k]:.3f} / {r1['scores']['family']['candidate_ridge'][k]:.3f} mean study-median abs ln | {('Baseline proxy' if k == 'practice' else 'Frozen transfer gate not achieved')} |\n"
    table += f"| R2 Two local torque calibration points | 4 withheld bore means, one study | mean abs ln {r2['metrics']['candidate']['mean_abs_ln']:.3f}; practice {r2['metrics']['practice']['mean_abs_ln']:.3f}; max {r2['metrics']['candidate']['max_abs_ln']:.3f} | Frozen retrospective gain passes |\n"
    table += f"| R3 Three points + conditional inverse set | 2 remaining bore means, same study | abs ln {r3['predictions'][0]['abs_ln']:.3f} / {r3['predictions'][1]['abs_ln']:.3f} | Fitted model query passes; physical guarantee UNKNOWN |\n"
    table += '| R4 Available drill menu + local calibration | Published selected bore means | Df3.3/3.6 mm →26.0/24.8 Ncm;2/2 in20–30 Ncm | Retrospective query passes; general transfer UNKNOWN |\n'
    body = f"# X68: local torque measurements make a bore-response query possible\n\nTwo measured endpoint torques in the SAME published implant/material/cortex regime reduce mean absolute log error by {100 * gain:.1f}% against the area-density practice proxy on four intermediate arm means. The independent measured referent is [Bayarchimeg2013 Tables2 and5, pp.33–34](https://jpis.org/pdf/10.5051/jpis.2013.43.1.30). This is a retrospective information-link result in one study. A patient drill choice and radial pressure remain unidentified.\n\n{table}\nMeasurements are **POPULATION arm means**; fitted responses and inverse candidates are **PHENOMENOLOGICAL**. All log-error numbers are dimensionless. The R1 metric averages each study's median equally; R2/R3 errors concern individual arm means. The old K26 values0.32/0.35 use another population and weighting and are not directly comparable.\n\nThe pooled information model fails the frozen >=20% improvement and abs-ln<=ln(1.5) gates. Added cortex alone changes study-out error0.445→0.420 and family-out0.418→0.385, while drilling worsens it. The both-model predicts the WRONG drilling direction on12/12 matched bore contrasts and meets both direction/effect criteria in12/24 cortex contrasts. Pair contrasts share source arms and are not36 independent trials. The descriptive95th percentile absolute log residual gives a2.56× error factor for the both-model; this is not calibrated future coverage or a physical bound. The two available inverse groups yield0/2 target hits; generalization is UNKNOWN_COVERAGE because they belong to one family, below the frozen three-family requirement.\n\nSame-information controls were run: R1 weighted least squares confirms failure (study-out both0.476 vs baseline0.431); R2 ordinary bore interpolation also stays below the20% absolute-error limit (mean0.121, max0.154); R3 Lagrange evaluation agrees numerically. On the finite R4 menu, ordinary interpolation hits1/2 target groups. No general method superiority is claimed from two exposed regimes.\n\nThe target query CAN choose among the actual source-tested bore options retrospectively: local calibration selects3.3mm without cortex and3.6mm with1.5mm cortex; withheld means26.0/24.8Ncm both hit the frozen20–30Ncm band. R1 practice's recorded choices hit1/2; R1 both-model0/2. R4 is a capability query over published manufacturing options, not independent patient or multi-study validation. It retains GENERAL_TRANSFER_UNKNOWN and a null guaranteed fixed bore.\n\n## What the source information does and does not identify\n\nArea-density summary is machine-identical for Df2.7 and3.3mm in Bayarchimeg Table2: identity error0, measured torques39.2 and26.0Ncm, difference13.2Ncm. Adding Df separates this pair; it is not globally sufficient. The finite-input obstruction persists: two constructed monotone curves have bitwise-identical endpoint torque summaries yet differ2Ncm in the middle. That witness is mathematical, not an independent physical dataset.\n\nTotal mean torque16.2Ncm is bitwise identical for Table2 Df3.6/no cortex and Table5 Df3.8/cortex1.5mm: identity error0, measured ISQ52.5 vs56.8, difference4.3. One bit identifying cortical-layer presence distinguishes this pair; Df alone also separates it. Neither is established as globally sufficient for stability or pressure. ISQ is an independently reported response, not an SI stiffness or pressure measurement.\n\nThree-point quadratic fits have exact-rational certified derivative bounds, conservatively displayed as[-48.115441,-7.722943] and[-49.282426,-5.651645]Ncm/mm throughout their measured intervals. Full outward-rounded endpoints/rationals are in SCORES_SUPPLEMENT.json. These certify the fitted polynomial only. Its physical remainder bound is MISSING. At the research target25Ncm, monotonicity/exact mean inputs give root outer sets[3.0,3.6] and[3.3,3.8]mm. They do not guarantee that any chosen fixed bore hits20–30Ncm in a new specimen. Two-point continuous candidates3.284906/3.474205mm were not physically validated.\n\nThe R4 discrete-choice sufficiency test also fails: two globally decreasing positive responses share bitwise-identical endpoint means39.2/16.2Ncm and the same menu, identity error0, but choose3.3 vs3.0mm, a0.3mm downstream difference. Exact rational derivative bounds certify monotonicity of this mathematical witness; it is not a physical dataset. One interior response distinguishes these two quadratic curves; arbitrary physical curvature still needs an independently justified error enclosure.\n\nMeasured motor torque includes cutting, crushing and friction. Mapping it to pressure needs independent contact geometry and calibrated separation of those contributions. The runnable operator emits `radial_pressure_MPa: null`.\n\n## Coverage and data availability\n\n53 arms extracted;38 retained;15 rejected (**28.3%**):12 ambiguous conical bore profiles and3 repeated conditions. Six studies become four conservative lab/implant families; related Chieti studies are held out together. Every arm has a table/paragraph locator and source hash. PU density is manufacturer nominal. Bayarchimeg cortex grade50/epoxy and table n5 versus methods20 remain explicit ambiguities. Sugiura uses a stepped bore/cortical counterbore. Chavarri's suprabony neck and the2023 four/five-mm plate experiment show why nominal L is not actual engagement.\n\nMachine equality refers to the published rounded arm means, not identical individual specimens. The equal16.2Ncm pair has source SD2.56/2.17Ncm and ISQ SD0.74/1.33 (`raw/ISQ_SOURCE_CHECK.json`). R1 conservatively collapses repeated conditions; differing ISQ/SD across tables means actual specimen duplication is not proven.\n\nAmong200 local keyword candidates,4 were extracted,9 received bounded complete-case checks,3 remain table-preview-only and184 metadata-only. Deferred records are not exclusions or evidence of absence. Human regional HU/torque marginals, categorized torque and drilling torque are retained separately, never pooled. The separately checked porcine-rib source[PMC10605303](https://doi.org/10.3390/dj11100227) reports regional thread heights0.4/0.5mm and pitch1.35mm, but lacks matched actual bore/cortex/density; no three complete thread-informed families are available.\n\nToothFairy2: {cbct['ToothFairy2']['training_image_count']} training and {cbct['ToothFairy2']['test_image_count']} test images in THIS ZIP, example spacing0.3mm; archive metadata erroneously lists numTraining/numTest0, so counts use actual members. The earlier HANDOFF_R2 expectation of50 test images was not verified and is corrected: none occur in this archive. Jawbone labels do not identify the inner cortex surface. MMDental:403 volumes,2124 journal rows,0 segmentation/mask-named members.76 rows mention torque units in any context, with0 tested insertion-torque phrase matches. The bounded phrase audit is not an exhaustive absence proof; prescribed abutment torque must not be relabeled insertion torque. No patient text or voxel arrays were exported. Regional cortex is potentially measurable from the images, but has not been measured/validated here; absolute density, actual final bore and thread/core geometry are not calibrated by these schemas.\n\nRequired K26 input edges: bore/contact profile **PER_SURFACE_REGION, HANDOVER** into insertion; individual torque **PER_TOOTH, SIMULTANEOUS** only after individual measurements exist. Article means stay **POPULATION**. Pressure-to-stability is a regional HANDOVER edge with UNKNOWN pressure. Consumers may aggregate; the source never fabricates finer observations.\n\n## Reproduction, verification and limits\n\nRun `./run_all.sh` offline in this directory. It rebuilds extracted arms, all fold predictions/scores, header/schema audit, figure, results and verification. Existing frozen predictions must match exactly or the run stops. Python3.10/NumPy2.2.6 performs the numerical replay; system Matplotlib with `python3 -s` makes the figure. Source files and the two ZIPs must be available at the recorded local paths. No full unzip, GPU or large arrays.\n\nAll verification checks pass; deliberately corrupted source bytes/torque, model/control predictions, derivative sign and monotonicity are rejected. Independent direct weighted-design WLS agrees within {verify['independent_WLS_max_relative_difference']:.2g} relative difference; Lagrange within {verify['independent_Lagrange_max_relative_difference']:.2g}. Source SDs are preserved without treating them as hard bounds.\n\nPrereg criteria and predictions were frozen before scoring, but the literature outcomes had already been seen: retrospective, not blind acquisition. Formal R2/R3 decomposition files were consolidated after scoring; pre-run equations and closure restrictions are in their preregs. A serialization-only repair in R2 and an interval-input ordering repair changed code hashes but not frozen predictions; originals/receipts and failures are preserved. Graph feedback remains PENDING_INDEPENDENT_REVIEW, with the existing missing goal-path blocker intact.\n\nNext decisive construction: independently measure actual regional bore/contact geometry plus a local torque-depth response; use three calibration conditions and at least two withheld validation conditions, with repeated specimens and frozen predictions before measurement. `LAB_VALIDATION_SPEC.json` specifies missing measurements and costs. No clinical choice, general transfer or10× improvement is supported.\n"
    (ROOT / 'RESULTS.md').write_text(body)
    license_names = {'PMC3596632': 'CC BY-NC3.0', 'PMC8431239': 'CC BY4.0', 'PMC7216137': 'CC BY4.0', 'PMC7071536': 'CC BY; version not specified in XML', 'PMC7150554': 'CC BY-NC-SA4.0', 'PMC10384017': 'CC BY4.0', 'PMC10563580': 'CC BY; version not specified in XML', 'PMC10847140': 'CC BY4.0', 'PMC10829676': 'CC BY-NC-ND4.0'}
    licenses = '| Measurement source | License from local XML |\n|---|---|\n' + '\n'.join((f"| [{pmc}](https://doi.org/{v['doi']}) | {license_names[pmc]} |" for (pmc, v) in sources.items()))
    readme = _release_expand(f"# X68 demo: measure the local response before choosing a research bore\n\nThe idea is to replace an unmeasured absolute insertion resistance with torque calibration in the same material/implant/cortex regime. Two published endpoint measurements let the demo predict four intermediate bore means; a third point permits a curvature-sensitive model and a conditional target-root interval. The external referent is [Bayarchimeg2013 Tables2/5](https://jpis.org/pdf/10.5051/jpis.2013.43.1.30), not our synthetic witness.\n\n```bash\ncd @DENTAL_IMPLEMENTATIONS@/X68\n./run_all.sh\n```\n\n{table}\n![Source measurements, held-out prediction and exact-summary failure](FIGURE_X68.png)\n\n**What does not hold:** the pooled cortex/underdrill model fails cross-study transfer; two or three calibration points do not bound physical curvature/repeatability. All source measurements are POPULATION means. There is no guaranteed patient drill selection and no identified radial pressure. The exact-mean monotone root intervals are0.6/0.5mm wide. The same total torque can have different measured ISQ. This is one study's retrospective calibration evidence, with source outcomes seen during extraction. A10× gain is not established.\n\nThe area-density baseline is the lane's practice proxy, fitted with the same source training information. It is not a measured clinical standard-of-care success rate. Ordinary interpolation given the same endpoint measurements also meets the20% absolute-error check; the gain is the new local measurement information.\n\nThe finite-menu query selects3.3/3.6mm and the published measured means26.0/24.8Ncm both hit the frozen20–30Ncm band. This answers a retrospective laboratory menu query. Its two endpoint-equivalent monotone alternatives can choose different bores; a guaranteed choice for a new specimen still lacks an error enclosure. Individual specimens were not tested here.\n\nOpen `RESULTS.md` for interpretation, `results.json` for quantities/provenance and `EXTRACTED_ARMS.csv` for the53 retained-and-rejected candidate records. `FROZEN_PREDICTIONS.json` links original prediction timestamps/hashes. `VERIFICATION.json` reports actual holdout checks and rejected injected errors. `LAB_VALIDATION_SPEC.json` gives the next experiment; it was not run. Standalone PNG/SVG figures can be exported.\n\nTo try the operator with your own LABORATORY calibration, copy the schema in `raw/LAB_QUERY_INPUT.json`, use two or three measured same-regime calibration conditions, record the resolution/units and available bore menu, then run:\n\n```bash\npython3 code/query.py --input raw/LAB_QUERY_INPUT.json\n```\n\nThe bundled input is source-derived; it reproduces the frozen finite choices. `LAB_QUERY_DEMO.json` contains the executable port response. Unknown regime compatibility, out-of-range options and nonmonotone fitted responses cause abstention. The operator always marks the physical response enclosure missing and a guaranteed bore null. It does not accept an ISQ value as pressure.\n\nDependencies are local Python3.10, NumPy2.2.6 and system Matplotlib3.5.1. The plot uses `python3 -s`/NumPy1.21.5 to avoid the user's NumPy2/old-Matplotlib binary mismatch; numerical prediction replay uses the original NumPy2 environment. The script accesses local XML paths in `raw/source_manifest.json` and ZIP paths in `CBCT_AVAILABILITY.json`. It reads archive directories, one header each and aggregate journal schema; no full volume unzip or patient text output. It writes a few MB and uses4 threads; no >=4GB or GPU job is needed.\n\nDataset licenses: ToothFairy2 **CC BY-SA4.0** (archive metadata; semantic labels/header schema only), MMDental **CC BY4.0** ([dataset publication](https://doi.org/10.1038/s41597-025-05398-7); aggregate schema/header only). No images, journal text or personal records are redistributed. Published measurement sources have their own licenses below; this collection is not assigned a blanket permissive license. Check attribution/noncommercial/share-alike/no-derivatives restrictions before redistributing source-derived material.\n\n{licenses}\n\nRe-running changes measured runtime fields and therefore the results.json hash. The original round prediction receipts remain immutable. Refresh the pending graph feedback receipt after a rerun; do not reuse a previous result hash for review.\n")
    (ROOT / 'README_DEMO.md').write_text(readme)
    packet = read('raw/GRAPH_PACKET.json')
    record = dict(target_id='DENT-PROC-INSERT-S4-TORQUE', result_file='results/LANE_X68_INSERTION_TORQUE/results.json', sha256=sha(ROOT / 'results.json'), review_state='PENDING_INDEPENDENT_REVIEW', source_generation=packet.get('result_binding_template', {}).get('source_generation'), outcome='FAILED', negative_result=True, measured_quantity='R1 cross-study scalar-information torque error; R2 local response error; R4 selected-bore measured mean torque', units='Ncm for measurements; dimensionless abs ln for error; mm for nominal bore menu', uncertainty='POPULATION arm means and source SD; retrospective same-study calibration only; physical error enclosure MISSING; patient bore and radial pressure UNKNOWN', population_regime='PU manufacturer nominal density,6 studies4 conservative families; drill-varying local selection1 study2 regimes', preregistered_gate='R1 both<=0.8practice and<=ln1.5 in study/family holdout:FAIL. R2 max<=ln1.2 and mean<=0.5practice:PASS retrospective. R3 heldout<=ln1.2/numerical parity:PASS conditional. R4 >=80pct selected means20-30Ncm,>=2regimes:2/2PASS retrospective;3family generalization UNKNOWN.', baseline='Area-density proxy; R1 study0.4446426913/family0.4175903482 versus both0.4499000457/0.4274819599. Same-information WLS/interpolation/Lagrange checks separately scored.', scope='Failed cross-study scalar transfer is the target negative result; local calibration and finite menu capability do not promote native proof or patient guarantee.', coverage_proposals='Review missing K26-to-DENT-GOAL path and regional actual-bore/contact input relation. No source/generated graph changed.', next_construction='LAB_VALIDATION_SPEC.json: actual bore/contact metrology plus paired torque-depth,3calibration and2withheld conditions, repeated specimens/multiple families', round_claim_types={'R1': 'information_link', 'R2': 'information_link', 'R3': 'capability', 'R4': 'capability'})
    dump('GRAPH_FEEDBACK.json', record)
    print(json.dumps({'R1': r1['verdict'], 'R2': r2['verdict'], 'R3': r3['verdict'], 'R4': r4['verdict'], 'verification': verify['status'], 'patient_bore_choice': 'UNKNOWN', 'radial_pressure_MPa': None, 'figure': 'FIGURE_X68.png'}, indent=2))
if __name__ == '__main__':
    main()
